import React, { useState, useEffect } from "react";

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState("");
  const [error, setError] = useState(null);

  useEffect(() => {
    const html = document.documentElement;
    html.classList.toggle("dark", darkMode);
  }, [darkMode]);

  const handleSubmit = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });

      const data = await res.json();
      console.log("Backend response:", data);

      setRecipes(data.recipe || data); // fallback to whole response
      setError(null);
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError("Failed to generate recipes. Please try again later.");
      setRecipes("");
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4 transition-colors duration-300">
      <div className="absolute top-4 right-4">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-5xl">
        {/* LEFT SIDE - FORM */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6">
          <div className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </div>
          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="ingredients">
              Ingredients
            </label>
            <input
              id="ingredients"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              type="text"
              placeholder="Enter ingredients"
              value={ingredients}
              onChange={(e) => setIngredients(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="mealType">
              Meal Type
            </label>
            <select
              id="mealType"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={mealType}
              onChange={(e) => setMealType(e.target.value)}
            >
              <option>Breakfast</option>
              <option>Lunch</option>
              <option>Dinner</option>
              <option>Snack</option>
            </select>
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="cuisine">
              Cuisine Preference
            </label>
            <input
              id="cuisine"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              type="text"
              placeholder="e.g., Italian, Mexican"
              value={cuisine}
              onChange={(e) => setCuisine(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="cookingTime">
              Cooking Time
            </label>
            <select
              id="cookingTime"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={cookingTime}
              onChange={(e) => setCookingTime(e.target.value)}
            >
              <option>Less than 30 minutes</option>
              <option>30-60 minutes</option>
              <option>More than 1 hour</option>
            </select>
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="complexity">
              Complexity
            </label>
            <select
              id="complexity"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={complexity}
              onChange={(e) => setComplexity(e.target.value)}
            >
              <option>Beginner</option>
              <option>Intermediate</option>
              <option>Advanced</option>
            </select>
          </div>

          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full"
          >
            Generate Recipe
          </button>
        </div>

        {/* RIGHT SIDE - RESULT DISPLAY */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md p-6 overflow-auto">
          <h2 className="text-xl font-bold mb-4 text-center">Recipe Output</h2>
          {error && (
            <p className="text-red-500 dark:text-red-400 text-center mb-4">
              {error}
            </p>
          )}
          {!recipes ? (
            <p className="text-gray-500 dark:text-gray-300 text-center">
              No recipes yet. Try generating one!
            </p>
          ) : typeof recipes === "string" ? (
            <div
              className="prose dark:prose-invert max-w-none"
              dangerouslySetInnerHTML={{ __html: recipes }}
            />
          ) : (
            <pre className="text-sm whitespace-pre-wrap">
              {JSON.stringify(recipes, null, 2)}
            </pre>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
